/** Chamfered 60x60 square outline (3-unit corner cuts). */
function makeShellOutline() {
  const s = new THREE.Shape();
  const h = SHELL_SIZE / 2; // 30
  const c = 3;              // chamfer
  s.moveTo(-h + c, h);
  s.lineTo(h - c, h);
  s.lineTo(h, h - c);
  s.lineTo(h, -h + c);
  s.lineTo(h - c, -h);
  s.lineTo(-h + c, -h);
  s.lineTo(-h, -h + c);
  s.lineTo(-h, h - c);
  s.closePath();
