// ANIMATION: update
// ============================================================
function updateAnimation(now) {
  if (animState === 'exploding' || animState === 'collapsing') {
    const forward = animState === 'exploding';
    const start = forward ? animStart : collapseStart;
    const elapsed = Math.max(0, now - start);
    const maxTime = DURATION + MAX_STAGGER;

    let allDone = true;
    for (const p of parts) {
      const raw = (elapsed - p.delay) / DURATION;
      const clamped = Math.max(0, Math.min(1, raw));
      const eased = easing(clamped);

      let t = eased;
      if (!forward) t = 1 - eased;

      p.group.position.lerpVectors(p.from, p.to, t);

      const op = p.fromOpacity + (p.toOpacity - p.fromOpacity) * t;
      for (const m of p.materials) {
        m.opacity = op;
      }

      if (raw < 1) allDone = false;
    }

    if (forward && elapsed >= maxTime && allDone) {
      animState = 'exploded';
      setHintVisible(false);
      showLabels();
    } else if (!forward && elapsed >= maxTime && allDone) {
      // Ensure exact assembled values.
      for (const p of parts) {
        p.group.position.copy(p.from);
        for (const m of p.materials) m.opacity = p.fromOpacity;
      }
      animState = 'assembled';
      setHintVisible(true);
    }
  }
}

