// GEOMETRY: HUB
// ============================================================
function createHub() {
  const group = new THREE.Group();
  // Disc with central circular hole and nearby square drive hole.
  const shape = new THREE.Shape();
  shape.absarc(0, 0, 5, 0, Math.PI * 2, false);
  const centerHole = new THREE.Path();
  centerHole.absarc(0, 0, 1.3, 0, Math.PI * 2, true);
  shape.holes.push(centerHole);
  const squareHole = new THREE.Path();
  const sq = 0.9;
  squareHole.moveTo(1.8 - sq, -sq);
  squareHole.lineTo(1.8 + sq, -sq);
  squareHole.lineTo(1.8 + sq, sq);
  squareHole.lineTo(1.8 - sq, sq);
  squareHole.closePath();
  shape.holes.push(squareHole);

  const geo = makeFlatExtrude(shape, 0.4);
  const mat = blueprintFill();
  addEdgedMesh(group, geo, mat);
