// ============================================================
// GEOMETRY: BOTTOM SHELL
// ============================================================
function createBottomShell() {
  const group = new THREE.Group();

  // Main shell with central spindle hole, shutter window, and write-protect notch.
  const shape = makeShellOutline();
  // (b) central circular hole (diameter 14)
  shape.holes.push(new THREE.Path().absarc(0, 0, 7, 0, Math.PI * 2, false));
