  createAnnotation('DUST LINER (LOWER)', new THREE.Vector3(18, 0, -18), new THREE.Vector3(30, 4, -26));
  createAnnotation('BOTTOM SHELL', new THREE.Vector3(20, -15, 0), new THREE.Vector3(31, -21, 0));
  createAnnotation('LIFTER', new THREE.Vector3(0, -15, -8), new THREE.Vector3(0, -23, -16));
  createAnnotation('SHUTTER SPRING', new THREE.Vector3(5, -15, 23), new THREE.Vector3(14, -22, 31));
  createAnnotation('WRITE PROTECT NOTCH', new THREE.Vector3(26, -15, -26), new THREE.Vector3(38, -22, -38));
  createAnnotation('SHUTTER', new THREE.Vector3(-30, -15, 30), new THREE.Vector3(-40, -22, 38));
