// ============================================================
// DASHED LINES
// ============================================================
const dashedGroup = new THREE.Group();
const dashLines = [];
scene.add(dashedGroup);

function makeDashedLine(a, b) {
  const pts = [new THREE.Vector3(...a), new THREE.Vector3(...b)];
  const geo = new THREE.BufferGeometry().setFromPoints(pts);
  const mat = new THREE.LineDashedMaterial({
    color: BLUE,
    dashSize: 4,
    gapSize: 4,
    transparent: true,
    opacity: 0
  });
  const line = new THREE.Line(geo, mat);
  line.computeLineDistances();
  line.visible = false;
  dashedGroup.add(line);
  dashLines.push(line);
  return line;
}

function createDashedLines() {
  // Four vertical lines through the shell corners: bottom shell -> top shell exploded.
  const corners = [
    [-26, -26], [26, -26], [-26, 26], [26, 26]
  ];
  corners.forEach(([x, z]) => {
