// ============================================================
// GEOMETRY: SHUTTER (opaque metal slide)
// ============================================================
function createShutter() {
  const group = new THREE.Group();

  // Outer plate 22 x 16, hole 6 x 14. Long axis = X (22), short axis = Z (16).
  // Hole short edge (6) is parallel to shutter long edge; long edge (14) parallel to short edge.
  const shape = new THREE.Shape();
  shape.moveTo(-11, -8);
  shape.lineTo(11, -8);
  shape.lineTo(11, 8);
  shape.lineTo(-11, 8);
  shape.closePath();

  // Left-biased rectangular hole (x from -5 to 1, z from -7 to 7).
  const hole = new THREE.Path();
  hole.moveTo(SHUTTER_HOLE.x, SHUTTER_HOLE.z);
  hole.lineTo(SHUTTER_HOLE.x, SHUTTER_HOLE.z + SHUTTER_HOLE.d);
  hole.lineTo(SHUTTER_HOLE.x + SHUTTER_HOLE.w, SHUTTER_HOLE.z + SHUTTER_HOLE.d);
  hole.lineTo(SHUTTER_HOLE.x + SHUTTER_HOLE.w, SHUTTER_HOLE.z);
  hole.closePath();
  shape.holes.push(hole);

  const geo = makeFlatExtrude(shape, 1);
  // OPAQUE metal plate - must not become a blueprint ghost in exploded mode.
  const mat = new THREE.MeshBasicMaterial({ color: 0x4a5568, side: THREE.DoubleSide });
  addEdgedMesh(group, geo, mat, BLUE, 1);
  return group;
}

// ============================================================
// GEOMETRY: WRITE PROTECT TAB
// ============================================================
function createWriteProtectTab() {
  const group = new THREE.Group();
  const geo = new THREE.BoxGeometry(3, 2, 3);
  const mat = blueprintFill();
  addEdgedMesh(group, geo, mat);
  return group;
}

// ============================================================
// BUILD SCENE / PARTS
// ============================================================
const topShell = createTopShell();
const dustLinerUpper = createDustLiner();
const magneticDisk = createMagneticDisk();
const hub = createHub();
const dustLinerLower = createDustLiner();
const bottomShell = createBottomShell();
const shutter = createShutter();
const writeProtectTab = createWriteProtectTab();

scene.add(topShell);
scene.add(dustLinerUpper);
scene.add(magneticDisk);
scene.add(hub);
scene.add(dustLinerLower);
scene.add(bottomShell);
scene.add(shutter);
scene.add(writeProtectTab);

// ============================================================
// ANIMATION: setupParts
// ============================================================
const parts = [];
const DURATION = 2600;       // each part's own travel time
const STAGGER = 80;          // ms between parts
const MAX_STAGGER = 6 * STAGGER; // 480 ms, total ~3.08s

function setupParts() {
  // [group, assembledPos, explodedPos, delayIndex, explodedOpacity]
  // Dust liner lower stays at Y=0 by design (the bottom of the stack).
  const defs = [
    { group: topShell,         from: [0, 1.5, 0],  to: [0, 45, 0], delay: 0 },
    { group: dustLinerUpper,   from: [0, 1.0, 0],  to: [0, 30, 0], delay: 1 },
    { group: magneticDisk,     from: [0, 0.5, 0],  to: [0, 15, 0], delay: 2 },
    { group: hub,              from: [0, 0.7, 0],  to: [0, 18, 0], delay: 3 },
    { group: dustLinerLower,   from: [0, 0.0, 0],  to: [0, 0, 0],  delay: 4 },
    { group: bottomShell,      from: [0, -1.5, 0], to: [0, -15, 0], delay: 5 },
    { group: shutter,          from: [HEAD_WINDOW.x - SHUTTER_HOLE.x, -1.5, HEAD_WINDOW.z - SHUTTER_HOLE.z], to: [-30, -15, 30], delay: 4 },
    { group: writeProtectTab,  from: [26, -1.0, -26], to: [35, -15, -35], delay: 5 }
  ];

  defs.forEach((d) => {
    const from = new THREE.Vector3(...d.from);
    const to = new THREE.Vector3(...d.to);
    d.group.position.copy(from);
    const mats = collectAnimatedMaterials(d.group);
    // Assembled state always starts visually opaque (disk 1.0, shells 1.0).
    mats.forEach((m) => { m.opacity = 1; m.depthWrite = true; });
    const isDisk = d.group === magneticDisk;
    const isShutter = d.group === shutter;
    const toOpacity = isDisk ? 0.5 : 0.08;
    const fromOpacity = 1;
    parts.push({
      group: d.group,
      from,
      to,
      delay: d.delay * STAGGER,
      materials: mats,
      fromOpacity,
      toOpacity: isShutter ? 1 : toOpacity
    });
  });
}
setupParts();

// ============================================================
// LABELS + LEADER LINES
// ============================================================
const labelGroup = new THREE.Group();
const labelItems = []; // { css, line }
let labelRevealToken = 0; // invalidates pending label fades when hiding
scene.add(labelGroup);

function createAnnotation(text, anchor, pos) {
  const div = document.createElement('div');
  div.className = 'annotation-label';
  div.textContent = text;

  const css = new CSS2DObject(div);
  css.position.copy(pos);
  css.visible = false;
  labelGroup.add(css);

  const pts = [anchor.clone(), pos.clone()];
  const geo = new THREE.BufferGeometry().setFromPoints(pts);
  const line = new THREE.Line(
    geo,
    new THREE.LineBasicMaterial({ color: BLUE, transparent: true, opacity: 0 })
  );
  line.visible = false;
  labelGroup.add(line);

  labelItems.push({ css, line, el: div });
  return { css, line };
}

function createAllLabels() {
  // Anchors are on exploded parts; label positions are slightly offset.
  createAnnotation('HD NOTCH', new THREE.Vector3(-26, 45, -26), new THREE.Vector3(-26, 54, -34));
  createAnnotation('TOP SHELL', new THREE.Vector3(20, 45, 0), new THREE.Vector3(30, 50, 0));
  createAnnotation('DUST LINER (UPPER)', new THREE.Vector3(14, 30, -16), new THREE.Vector3(32, 34, -24));
  createAnnotation('MAGNETIC DISK', new THREE.Vector3(18, 15, 0), new THREE.Vector3(31, 19, 0));
  createAnnotation('HUB', new THREE.Vector3(0, 18, 0), new THREE.Vector3(0, 26, 0));
  createAnnotation('DUST LINER (LOWER)', new THREE.Vector3(14, 0, -16), new THREE.Vector3(30, 4, -26));
  createAnnotation('BOTTOM SHELL', new THREE.Vector3(20, -15, 0), new THREE.Vector3(31, -21, 0));
  createAnnotation('LIFTER', new THREE.Vector3(0, -15, -8), new THREE.Vector3(0, -23, -16));
  createAnnotation('SHUTTER SPRING', new THREE.Vector3(5, -15, 23), new THREE.Vector3(14, -22, 31));
  createAnnotation('WRITE PROTECT NOTCH', new THREE.Vector3(26, -15, -26), new THREE.Vector3(38, -22, -38));
  createAnnotation('SHUTTER', new THREE.Vector3(-30, -15, 30), new THREE.Vector3(-40, -22, 38));
  createAnnotation('WRITE PROTECT TAB', new THREE.Vector3(35, -15, -35), new THREE.Vector3(46, -23, -44));
}
createAllLabels();

// ============================================================
// DASHED LINES
// ============================================================
const dashedGroup = new THREE.Group();
const dashLines = [];
scene.add(dashedGroup);

function makeDashedLine(a, b) {
  const pts = [new THREE.Vector3(...a), new THREE.Vector3(...b)];
  const geo = new THREE.BufferGeometry().setFromPoints(pts);
  const mat = new THREE.LineDashedMaterial({
    color: BLUE,
    dashSize: 4,
    gapSize: 4,
    transparent: true,
    opacity: 0
  });
  const line = new THREE.Line(geo, mat);
  line.computeLineDistances();
  line.visible = false;
  dashedGroup.add(line);
  dashLines.push(line);
  return line;
}

function createDashedLines() {
  // Four vertical lines through the shell corners: bottom shell -> top shell exploded.
  const corners = [
    [-26, -26], [26, -26], [-26, 26], [26, 26]
  ];
  corners.forEach(([x, z]) => {
    makeDashedLine([x, -15, z], [x, 45, z]);
  });
  // Oblique dashed lines for the two external small parts.
  makeDashedLine([-5, -15, 21], [-30, -15, 30]);   // shutter to bottom shell slot
  makeDashedLine([26, -15, -26], [35, -15, -35]);  // write-protect tab to bottom shell
}
createDashedLines();

// ============================================================
// ANIMATION STATE MACHINE
// ============================================================
let animState = 'assembled'; // assembled | exploding | exploded | collapsing
let animStart = 0;
let collapseStart = 0;
const hintEl = document.getElementById('hint');
const easing = (t) => {
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
};

function setHintVisible(visible) {
  hintEl.classList.toggle('hidden', !visible);
}

// === ANIMATION: explode trigger ===
function triggerExplode() {
  if (animState !== 'assembled') return;
  animState = 'exploding';
  animStart = performance.now();
  setHintVisible(false);
}

// === ANIMATION: collapse trigger ===
function triggerCollapse() {
  if (animState !== 'exploded') return;
  hideLabels();
  animState = 'collapsing';
  // Give the label CSS fade ~350ms before parts begin moving back.
  collapseStart = performance.now() + 350;
}

// ============================================================
// ANIMATION: update
// ============================================================
function updateAnimation(now) {
  if (animState === 'exploding' || animState === 'collapsing') {
    const forward = animState === 'exploding';
    const start = forward ? animStart : collapseStart;
    const elapsed = Math.max(0, now - start);
    const maxTime = DURATION + MAX_STAGGER;


    let allDone = true;
    for (const p of parts) {
      const raw = (elapsed - p.delay) / DURATION;
      const clamped = Math.max(0, Math.min(1, raw));
      const eased = easing(clamped);

      let t = eased;
      if (!forward) t = 1 - eased;

      p.group.position.lerpVectors(p.from, p.to, t);

      const op = p.fromOpacity + (p.toOpacity - p.fromOpacity) * t;
      for (const m of p.materials) {
        m.opacity = op;
        // Keep assembled state solid, but let exploded blueprint parts become ghost-like.
        m.depthWrite = op > 0.5;
      }

      if (raw < 1) allDone = false;
    }

    if (forward && elapsed >= maxTime && allDone) {
      animState = 'exploded';
      setHintVisible(false);
      showLabels();
    } else if (!forward && elapsed >= maxTime && allDone) {
      // Ensure exact assembled values.
      for (const p of parts) {
        p.group.position.copy(p.from);
        for (const m of p.materials) { m.opacity = p.fromOpacity; m.depthWrite = true; }
      }
      animState = 'assembled';
      setHintVisible(true);
    }
  }
}

// ============================================================
// LABEL / DASHED LINE SHOW/HIDE
// ============================================================
function fadeLine(line, target, duration = 400) {
  const token = (line.userData.fadeToken || 0) + 1;
  line.userData.fadeToken = token;
  const start = performance.now();
  const startOpacity = line.material.opacity;
  const step = (now) => {
    if (line.userData.fadeToken !== token) return;
    const p = Math.min(1, (now - start) / duration);
    const e = easing(p);
    line.material.opacity = startOpacity + (target - startOpacity) * e;
    if (p < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
}

function showLabels() {
  const token = ++labelRevealToken;

  // 1) After 200ms, fade in dashed vertical / oblique lines.
  setTimeout(() => {
    if (token !== labelRevealToken) return;
    dashedGroup.visible = true;
    dashLines.forEach((line) => {
      line.visible = true;
      line.material.opacity = 0;
    });
    const t0 = performance.now();
    const dashFade = (now) => {
      if (token !== labelRevealToken) return;
      const p = Math.min(1, (now - t0) / 400);
      const e = easing(p);
      dashLines.forEach((line) => { line.material.opacity = e; });
      if (p < 1) requestAnimationFrame(dashFade);
    };
    requestAnimationFrame(dashFade);
  }, 200);

  // 2) Then labels fade in top-to-bottom, 60ms apart.
  setTimeout(() => {
    if (token !== labelRevealToken) return;
    labelItems.forEach((item, i) => {
      setTimeout(() => {
        if (token !== labelRevealToken) return;
        item.css.visible = true;
        item.line.visible = true;
        item.line.material.opacity = 0;
        fadeLine(item.line, 1, 400);
        // Force reflow so the CSS transition from 0 to 1 actually plays.
        void item.el.offsetWidth;
        item.el.style.opacity = '1';
      }, i * 60);
    });
  }, 400);
}

function hideLabels() {
  // Invalidate any pending label reveal timers.
  labelRevealToken++;
  // Fade CSS labels out.
  labelItems.forEach((item) => {
    item.el.style.opacity = '0';
    item.line.visible = true;
    fadeLine(item.line, 0, 300);
    setTimeout(() => {
      item.line.visible = false;
      item.css.visible = false;
    }, 350);
  });
  // Fade dashed lines out.
  dashLines.forEach((line) => {
    line.material.opacity = 0;
    setTimeout(() => { line.visible = false; }, 400);
  });
}

// ============================================================
// KEYBOARD
// ============================================================
window.addEventListener('keydown', (e) => {
  if (e.code === 'Space') {
    e.preventDefault();
    if (animState === 'assembled') triggerExplode();
    else if (animState === 'exploded') triggerCollapse();
    // Ignore presses while animating.
  }
});

// ============================================================
// RENDER LOOP
// ============================================================
function animate(now) {
  requestAnimationFrame(animate);
  updateAnimation(now);
  controls.update();
  renderer.render(scene, camera);
  labelRenderer.render(scene, camera);
}
requestAnimationFrame(animate);

// ============================================================
// SELF-CHECK COMMENTS (shutter + openings)
// ============================================================
/*
 * SHUTTER SELF CHECK
